sys_ws_operation.operation_script:
(function process(request, response) {
    try {
        var body = request.body.data;  // Veriff sends JSON payloads
		var id = "";
        var status = "";
		if (body.verification) {
            id = body.verification.id;
            status = body.verification.status;
        } else {
            id = body.id;
            status = body.action;
        }
        gs.info("Veriff webhook received: " + JSON.stringify(body));
		gs.info("id " + id);
		gs.info("action " + status);

        // Example: store in a log table
        var gr = new GlideRecord("x_vuram_financia_0_fcc_kyc_individual_details");
		gr.addQuery('session_id',id);
		gr.query();
		if(gr.next()){
			gr.video_kyc_status = status;
			gr.update();
		}
		else{
			var gr1 = new GlideRecord("x_vuram_financia_0_fcc_kyc_entity_details");
			gr1.addQuery('session_id',id);
			gr1.query();
			if(gr1.next()){
				gr1.video_kyc_status = status;
				gr1.update();
			}
		}

        // gr.description = JSON.stringify(body);
        // gr.insert();
        response.setStatus(200);
        response.setBody({received: true});
		//return body;
    } catch (e) {
        gs.error("Error in Veriff webhook: " + e.message);
        response.setStatus(500);
        response.setBody({error: e.message});
    }
})(request, response);
